// Builds the docmd sidebar from the docs tree, ordered and labelled the way the Docusaurus
// autogenerated sidebar was, so contributors keep using the same conventions:
//
// - A page's label is its `sidebar_label` or `title` front matter, else its first `# ` heading,
//   else its file name. `sidebar_position` orders it among its siblings.
// - A folder becomes a group. `_category_.json` gives its `label`, `position` and `collapsed`.
// - A folder's `index.md` or `README.md` becomes the group's own page. Without a
//   `_category_.json`, the group takes that page's label and position.
// - Unpositioned entries follow positioned ones, in file name order. Names starting with `_` and
//   folders with no pages are left out.
//
// docmd's own automatic sidebar only sorts alphabetically, which is why this exists. Only flat
// `key: value` front matter is read, which is all the docs use.

import fs from "node:fs";
import path from "node:path";
import { fenceTracker } from "./markdown-fences.mjs";

const INDEX_FILES = ["index.md", "readme.md"];

function readFrontMatter(source) {
  const block = source.match(/^---\r?\n([\s\S]*?)\r?\n---/);
  const data = {};
  for (const line of block ? block[1].split(/\r?\n/) : []) {
    const pair = line.match(/^([A-Za-z_][\w-]*):\s*(.*?)\s*$/);
    if (pair) {
      data[pair[1]] = pair[2].replace(/^(["'])(.*)\1$/, "$2");
    }
  }
  return data;
}

// A heading's text without inline Markdown, as Docusaurus showed it: images dropped, links reduced
// to their text and code ticks removed. Emphasis is left, as underscores appear in names.
function plainText(markdown) {
  return markdown
    .replace(/!\[[^\]]*\]\([^)]*\)/g, "")
    .replace(/\[([^\]]*)\]\([^)]*\)/g, "$1")
    .replace(/`+([^`]+?)`+/g, "$1")
    .trim();
}

// The first level-one heading outside fenced code, so a `# comment` in a shell example is skipped.
function firstHeading(source) {
  const inCode = fenceTracker();
  for (const line of source.replace(/^---\r?\n[\s\S]*?\r?\n---/, "").split(/\r?\n/)) {
    const heading = !inCode(line) && line.match(/^#\s+(.+?)(?:\s+#+)?\s*$/);
    if (heading) {
      return plainText(heading[1]);
    }
  }
  return null;
}

function readPage(file, url) {
  const source = fs.readFileSync(file, "utf8");
  const frontMatter = readFrontMatter(source);
  const position = Number.parseFloat(frontMatter.sidebar_position);
  return {
    title: frontMatter.sidebar_label || frontMatter.title || firstHeading(source) || path.basename(file, ".md"),
    position: Number.isNaN(position) ? undefined : position,
    path: url,
  };
}

function readCategory(dir) {
  const file = path.join(dir, "_category_.json");
  return fs.existsSync(file) ? JSON.parse(fs.readFileSync(file, "utf8")) : {};
}

function byPosition(a, b) {
  return (a.position ?? Infinity) - (b.position ?? Infinity);
}

function readFolder(dir, url) {
  const entries = fs
    .readdirSync(dir, { withFileTypes: true })
    .filter((entry) => !entry.name.startsWith("_") && !entry.name.startsWith("."))
    .sort((a, b) => (a.name < b.name ? -1 : a.name > b.name ? 1 : 0));

  let indexPage = null;
  const items = [];

  for (const entry of entries) {
    const full = path.join(dir, entry.name);

    if (entry.isFile() && entry.name.endsWith(".md")) {
      if (INDEX_FILES.includes(entry.name.toLowerCase())) {
        // index.md wins over README.md, as it does when docmd picks the folder's page.
        if (indexPage === null || entry.name.toLowerCase() === "index.md") {
          indexPage = readPage(full, url);
        }
        continue;
      }
      items.push(readPage(full, `${url}${entry.name.slice(0, -3)}/`));
      continue;
    }

    if (entry.isDirectory()) {
      const folder = readFolder(full, `${url}${entry.name}/`);
      if (folder.indexPage === null && folder.items.length === 0) {
        continue;
      }
      const category = readCategory(full);
      const group = {
        title: category.label ?? folder.indexPage?.title ?? entry.name,
        position: category.position ?? folder.indexPage?.position,
        path: folder.indexPage?.path,
      };
      if (folder.items.length > 0) {
        group.children = folder.items;
        // docmd opens a collapsible group only around the current page, so a Docusaurus
        // category that started expanded (collapsed: false) is shown as an always-open group.
        group.collapsible = category.collapsed !== false;
      }
      items.push(group);
    }
  }

  items.sort(byPosition);
  return { indexPage, items };
}

function stripPositions(items) {
  return items.map(({ position, children, ...item }) =>
    children ? { ...item, children: stripPositions(children) } : item,
  );
}

/** The sidebar for the docs folder at `docsDir`, in docmd's `navigation` format. */
export function buildNavigation(docsDir) {
  const { indexPage, items } = readFolder(docsDir, "/");
  if (indexPage !== null) {
    items.push(indexPage);
    items.sort(byPosition);
  }
  return stripPositions(items);
}
